const moonKeplerGM=(aKm,Pd)=>4*Math.PI*Math.PI*Math.pow(aKm*1e3,3)/Math.pow(Math.abs(Pd)*86400,2);

const moonOrbitalSpeed=(aKm,Pd)=>2*Math.PI*aKm/(Math.abs(Pd)*86400);

const moonBiggerThanMercury=r=>r>2439.7;

const bellE=th=>-Math.cos(th);

const bellLuneOmega=th=>2*(Math.PI-th);

const bellHolonomy=th=>Math.cos(bellLuneOmega(th)/2);

function bellCHSH(a,ap,b,bp){                          // S = E(a,b) + E(a,b') + E(a',b) - E(a',b')
  return bellE(Math.abs(a-b))+bellE(Math.abs(a-bp))+bellE(Math.abs(ap-b))-bellE(Math.abs(ap-bp));
}

const BELL_TSIRELSON=2*Math.SQRT2;

function fibSMatrix(){
  const d=Math.sqrt(1+PHI_R*PHI_R);
  return [[{re:1/d,im:0},{re:PHI_R/d,im:0}],[{re:PHI_R/d,im:0},{re:-1/d,im:0}]]; }

const FIB_N3=(a,b,c)=>((a+b+c)===1?0:1);

let FIB_FR=null;

function fibFR(){ if(!FIB_FR){ const i=1/PHI_R, s=1/Math.sqrt(PHI_R); FIB_FR=[[i,s],[s,-i]]; } return FIB_FR; }

function fibFsym(a,b,c,d,e,f){
  if(!FIB_N3(a,b,e)||!FIB_N3(e,c,d)||!FIB_N3(b,c,f)||!FIB_N3(a,f,d)) return 0;
  if(a===1&&b===1&&c===1&&d===1) return fibFR()[e][f];
  return 1;                                     /* any trivial label ⇒ the move is the identity */
}

function fibPentagon(){
  let worst=0,n=0;
  for(let a=0;a<2;a++)for(let b=0;b<2;b++)for(let c=0;c<2;c++)for(let d=0;d<2;d++)
  for(let e=0;e<2;e++)for(let f=0;f<2;f++)for(let g=0;g<2;g++)for(let k=0;k<2;k++)for(let l=0;l<2;l++){
    const L=fibFsym(f,c,d,e,g,l)*fibFsym(a,b,l,e,f,k);
    let R=0; for(let h=0;h<2;h++) R+=fibFsym(a,b,c,g,f,h)*fibFsym(a,h,d,e,g,k)*fibFsym(b,c,d,k,h,l);
    n++; worst=Math.max(worst,Math.abs(L-R));
  }
  return {worst,cases:n};
}

function fibHexagon(th1,thT){
  const R=(a,b,c)=>{ if(FIB_N3(a,b,c)===0) return [0,0];
    if(a===0||b===0) return [1,0];
    const t=(c===0)?th1:thT; return [Math.cos(t),Math.sin(t)]; };
  const cx=(x,y)=>[x[0]*y[0]-x[1]*y[1], x[0]*y[1]+x[1]*y[0]];
  let worst=0;
  for(let a=0;a<2;a++)for(let b=0;b<2;b++)for(let c=0;c<2;c++)for(let d=0;d<2;d++)
  for(let g=0;g<2;g++)for(let f=0;f<2;f++){
    let L=cx(R(c,a,g),[fibFsym(a,c,b,d,g,f),0]); L=cx(L,R(c,b,f));
    let Rt=[0,0];
    for(let e=0;e<2;e++){ let t=[fibFsym(c,a,b,d,g,e),0]; t=cx(t,R(c,e,d));
      t=cx(t,[fibFsym(a,b,c,d,e,f),0]); Rt=[Rt[0]+t[0],Rt[1]+t[1]]; }
    worst=Math.max(worst,Math.hypot(L[0]-Rt[0],L[1]-Rt[1]));
  }
  return worst;
}

let fibAxiomCache=null;

function fibAxioms(){
  if(fibAxiomCache) return fibAxiomCache;
  const P=fibPentagon();
  fibAxiomCache={pentagon:P.worst, cases:P.cases,
    hexRight:fibHexagon(4*Math.PI/5,-3*Math.PI/5),
    hexMirror:fibHexagon(-4*Math.PI/5,3*Math.PI/5),
    hexMixed:fibHexagon(4*Math.PI/5,3*Math.PI/5)};
  return fibAxiomCache;
}

function fibMonodromy(a,b){
  const S=fibSMatrix();
  return (S[a][b].re*S[0][0].re)/(S[a][0].re*S[0][b].re);
}

function hfFieldN(p,q,x,y,z){
  const r2=x*x+y*y+z*z, den=r2+1;
  const Z1re=2*x/den, Z1im=2*y/den, Z2re=2*z/den, Z2im=(r2-1)/den;
  const a1=Math.hypot(Z1re,Z1im), t1=Math.atan2(Z1im,Z1re);
  const a2=Math.hypot(Z2re,Z2im), t2=Math.atan2(Z2im,Z2re);
  const wmag=Math.pow(a1,p)/Math.pow(Math.max(a2,1e-12),q), wang=p*t1-q*t2;
  const wre=wmag*Math.cos(wang), wim=wmag*Math.sin(wang);
  const w2=wre*wre+wim*wim, dn=w2+1;
  return [2*wre/dn, 2*wim/dn, (w2-1)/dn];
}

const hfWMagOfTheta=th=>{ const c=Math.cos(th);
  return Math.sqrt((1+c)/Math.max(1e-15,1-c)); };

function hfPreimage(p,q,th,ph,N){
  const m=hfWMagOfTheta(th);
  let lo=1e-12, hi=1-1e-12;                            // |Z1|^p = m |Z2|^q, monotone in |Z1|
  const g=c=>Math.pow(c,p)-m*Math.pow(Math.sqrt(Math.max(0,1-c*c)),q);
  for(let i=0;i<200;i++){ const mid=(lo+hi)/2; if(g(mid)<0) lo=mid; else hi=mid; }
  const c1=(lo+hi)/2, c2=Math.sqrt(Math.max(0,1-c1*c1)), out=[], f10=ph/p;
  for(let k=0;k<N;k++){ const s=k/N*2*Math.PI, f1=f10+q*s, f2=p*s;
    const Z1re=c1*Math.cos(f1), Z1im=c1*Math.sin(f1), Z2re=c2*Math.cos(f2), Z2im=c2*Math.sin(f2);
    const d=1-Z2im;                                    // stereographic S^3 -> R^3
    out.push([Z1re/d, Z1im/d, Z2re/d]); }
  return out;
}

const hfHopfCharge=(p,q)=>p*q;

function hfEnergySlab(p,q,N,L,i0,i1){
  const h=2*L/N, dV=h*h*h;
  const f=(i,j,k)=>hfFieldN(p,q,-L+i*h,-L+j*h,-L+k*h);
  const cr=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
  const dt=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
  let E2=0, E4=0;
  for(let i=i0;i<i1;i++)for(let j=1;j<N;j++)for(let k=1;k<N;k++){
    const nx=f(i+1,j,k),px=f(i-1,j,k),ny=f(i,j+1,k),py=f(i,j-1,k),nz=f(i,j,k+1),pz=f(i,j,k-1);
    const dx=[(nx[0]-px[0])/(2*h),(nx[1]-px[1])/(2*h),(nx[2]-px[2])/(2*h)];
    const dy=[(ny[0]-py[0])/(2*h),(ny[1]-py[1])/(2*h),(ny[2]-py[2])/(2*h)];
    const dz=[(nz[0]-pz[0])/(2*h),(nz[1]-pz[1])/(2*h),(nz[2]-pz[2])/(2*h)];
    E2+=(dx[0]**2+dx[1]**2+dx[2]**2+dy[0]**2+dy[1]**2+dy[2]**2+dz[0]**2+dz[1]**2+dz[2]**2)*dV;
    const n=f(i,j,k);
    const F12=dt(n,cr(dx,dy)), F13=dt(n,cr(dx,dz)), F23=dt(n,cr(dy,dz));
    E4+=(F12*F12+F13*F13+F23*F23)*dV;
  }
  return {E2,E4};
}

function hfEnergyPure(p,q,N,L){ const E=hfEnergySlab(p,q,N,L,1,N);
  return {E2:E.E2, E4:E.E4, ...hfDerrick(E.E2,E.E4)}; }

function hfDerrick(E2,E4){
  const lam=Math.sqrt(E4/Math.max(E2,1e-300));
  return {lambda_star:lam, E_min:2*Math.sqrt(Math.max(0,E2*E4))};
}

const hfScaled=(E2,E4,lam)=>lam*E2+E4/Math.max(lam,1e-300);

function skBPField(x,y,centers,R,gamma,w,out){
  /* the Belavin-Polyakov rational map u = e^{i gamma} prod (z - a_k)/R, stereographically
     projected back to the sphere. EXACT: an anti-holomorphic factor for each antiskyrmion,
     and a radial reshaping of |u| that changes the wall width without touching the degree. */
  let ur=Math.cos(gamma), ui=Math.sin(gamma);
  for(let k=0;k<centers.length;k++){ const c=centers[k];
    const fr=(x-c.x)/R, fi=(c.s<0?-(y-c.y):(y-c.y))/R;
    const nr=ur*fr-ui*fi, ni=ur*fi+ui*fr; ur=nr; ui=ni; }
  const uu=Math.hypot(ur,ui), sc= uu>1e-6? Math.pow(uu,1/Math.max(0.35,w)-1) : 0;
  ur*=sc; ui*=sc; const V2=ur*ur+ui*ui, inv=1/(1+V2);
  out[0]=2*ur*inv; out[1]=2*ui*inv; out[2]=(V2-1)*inv;
  return out;
}

function skSampleBP(G,half,centers,R,gamma,w){   // the field on a square grid, as one flat array
  const M=new Float64Array(G*G*3), D=2*half/(G-1), t=[0,0,0];
  for(let j=0;j<G;j++)for(let i=0;i<G;i++){
    skBPField(-half+i*D,-half+j*D,centers,R,gamma,w,t);
    const k=(j*G+i)*3; M[k]=t[0]; M[k+1]=t[1]; M[k+2]=t[2]; }
  return {M,G,D,half};
}

function skSolidAngle(a0,a1,a2,b0,b1,b2,c0,c1,c2){
  const crx=b1*c2-b2*c1, cry=b2*c0-b0*c2, crz=b0*c1-b1*c0;
  const num=a0*crx+a1*cry+a2*crz;
  const den=1+(a0*b0+a1*b1+a2*b2)+(b0*c0+b1*c1+b2*c2)+(c0*a0+c1*a1+c2*a2);
  return 2*Math.atan2(num,den);
}

function skBergLuscher(M,G){
  const V=(i,j,k)=>M[(j*G+i)*3+k]; let Q=0;
  for(let j=0;j<G-1;j++)for(let i=0;i<G-1;i++){
    Q+=skSolidAngle(V(i,j,0),V(i,j,1),V(i,j,2), V(i+1,j,0),V(i+1,j,1),V(i+1,j,2), V(i+1,j+1,0),V(i+1,j+1,1),V(i+1,j+1,2))
      +skSolidAngle(V(i,j,0),V(i,j,1),V(i,j,2), V(i+1,j+1,0),V(i+1,j+1,1),V(i+1,j+1,2), V(i,j+1,0),V(i,j+1,1),V(i,j+1,2)); }
  return Q/(4*Math.PI);
}

function skEnergyPure(M,G,D,co,dmiBloch){
  const V=(i,j,k)=>M[(j*G+i)*3+k];
  let ex=0, dm=0, an=0, ze=0;
  for(let j=0;j<G-1;j++)for(let i=0;i<G-1;i++){
    const a0=V(i,j,0),a1=V(i,j,1),a2=V(i,j,2);
    const gx0=(V(i+1,j,0)-a0)/D, gx1=(V(i+1,j,1)-a1)/D, gx2=(V(i+1,j,2)-a2)/D;
    const gy0=(V(i,j+1,0)-a0)/D, gy1=(V(i,j+1,1)-a1)/D, gy2=(V(i,j+1,2)-a2)/D;
    ex+=gx0*gx0+gx1*gx1+gx2*gx2+gy0*gy0+gy1*gy1+gy2*gy2;
    an+=1-a2*a2; ze+=1-a2;
    dm+= dmiBloch ? (a0*gy2-a2*gy0)-(a1*gx2-a2*gx1) : a2*(gx0+gy1)-(a0*gx2+a1*gy2); }
  const dA=D*D, E={ex:(co.exchange??1)*0.5*ex*dA, dm:(co.dmi??0)*dm*dA,
    an:(co.aniso??0)*an*dA, ze:(co.field??0)*ze*dA};
  E.tot=E.ex+E.dm+E.an+E.ze;
  E.exchange_bare=0.5*ex*dA;                       // with the coupling set to one, for the bound
  return E;
}

const skBogomolny=Q=>4*Math.PI*Math.abs(Q);

const skGyrovector=s=>4*Math.PI*s;

function skThieleSolve(s,alpha,beta,d0,vsx,vsy,Fx,Fy){
  const G=skGyrovector(s), ad=Math.max(1e-9,alpha);
  const Rx=G*(-vsy)+beta*d0*vsx+Fx, Ry=G*(vsx)+beta*d0*vsy+Fy, det=ad*ad*d0*d0+G*G;
  return [(ad*d0*Rx+G*Ry)/det, (-G*Rx+ad*d0*Ry)/det];
}

function skHallAngle(s,alpha,beta,d0){
  const G=skGyrovector(s), D=d0===undefined?1:d0;
  return Math.atan2((beta-alpha)*D*G, alpha*beta*D*D+G*G);
}

function qpPhononOmega2(k,K,m1,m2,branch){
  const s2=Math.sin(k/2)**2, mm=4*m1*m2/((m1+m2)*(m1+m2));
  const disc=Math.sqrt(Math.max(0,1-mm*s2)), pre=K*(1/m1+1/m2);
  if(branch==='optical') return pre*(1+disc);
  /* 1 - sqrt(1 - x) is CATASTROPHIC at small x, and at small k that is the entire acoustic
     branch: written literally it loses every significant digit and the sound speed measured
     as a limit drifts by five per cent at k = 1e-6 instead of converging. Multiplying by the
     conjugate gives x/(1 + sqrt(1 - x)), which is the same number and is stable. */
  return pre*mm*s2/(1+disc);
}

const qpPhononOmega=(k,K,m1,m2,branch)=>Math.sqrt(Math.max(0,qpPhononOmega2(k,K,m1,m2,branch)));

const qpSoundSpeed=(K,m1,m2,a=1)=>a*Math.sqrt(K/(2*(m1+m2)));

const qpOpticalAtZero=(K,m1,m2)=>Math.sqrt(2*K*(1/m1+1/m2));

const qpZoneGap=(K,m1,m2)=>{ const hi=Math.max(m1,m2), lo=Math.min(m1,m2);
  return {acoustic:Math.sqrt(2*K/hi), optical:Math.sqrt(2*K/lo)}; };

const qpMagnonOmega=(k,J,S)=>8*J*S*Math.sin(k/2)**2;

const qpMagnonStiffness=(J,S,a=1)=>2*J*S*a*a;

const QP_A0_NM=0.0529177210903, QP_RY_MEV=13605.693122994;

const qpExcitonRadius=(mu,eps)=>QP_A0_NM*eps/mu;

const qpExcitonBinding=(mu,eps)=>QP_RY_MEV*mu/(eps*eps);

const qpExcitonInvariant=(mu,eps)=>qpExcitonBinding(mu,eps)*qpExcitonRadius(mu,eps)**2*mu;

const qpPolaronMass=alpha=>1+alpha/6;

const qpPolaronEnergy=alpha=>-alpha;

const qpVortexSpeed=(n,r,hbar,m)=>n*hbar/(m*Math.max(r,1e-300));

const qpCirculation=(n,hbar,m)=>n*2*Math.PI*hbar/m;

const qpCirculationFromLoop=(n,r,hbar,m)=>2*Math.PI*r*qpVortexSpeed(n,r,hbar,m);

const AUFBAU=[[1,0],[2,0],[2,1],[3,0],[3,1],[4,0],[3,2],[4,1],[5,0],[4,2],[5,1],[6,0],[4,3],[5,2],[6,1],[7,0],[5,3],[6,2],[7,1]];

const CONF_EXC={24:'[Ar] 3d5 4s1',29:'[Ar] 3d10 4s1',41:'[Kr] 4d4 5s1',42:'[Kr] 4d5 5s1',44:'[Kr] 4d7 5s1',45:'[Kr] 4d8 5s1',
 46:'[Kr] 4d10',47:'[Kr] 4d10 5s1',57:'[Xe] 5d1 6s2',58:'[Xe] 4f1 5d1 6s2',64:'[Xe] 4f7 5d1 6s2',78:'[Xe] 4f14 5d9 6s1',
 79:'[Xe] 4f14 5d10 6s1',89:'[Rn] 6d1 7s2',90:'[Rn] 6d2 7s2',91:'[Rn] 5f2 6d1 7s2',92:'[Rn] 5f3 6d1 7s2',93:'[Rn] 5f4 6d1 7s2',
 96:'[Rn] 5f7 6d1 7s2',103:'[Rn] 5f14 7s2 7p1'};

function atomConfig(Z){                                           // → [{n,l,c}] ground state
  const exc=CONF_EXC[Z];
  if(exc){ // parse the exception string beyond its noble core
    const CORE={'[Ar]':18,'[Kr]':36,'[Xe]':54,'[Rn]':86};
    const m=exc.match(/^\[(?:Ar|Kr|Xe|Rn)\]/)[0];
    const shells=atomConfig(CORE[m]);
    for(const tok of exc.slice(m.length).trim().split(/\s+/)){
      const mm=tok.match(/^(\d)([spdf])(\d+)$/);
      shells.push({n:+mm[1], l:'spdf'.indexOf(mm[2]), c:+mm[3]});
    }
    return shells;
  }
  const shells=[]; let left=Z;
  for(const [n,l] of AUFBAU){ if(left<=0) break;
    const cap=2*(2*l+1), c=Math.min(cap,left); shells.push({n,l,c}); left-=c; }
  return shells;
}

function slaterZeff(Z,shells,idx){                                // Slater's rules for shell idx
  const {n,l}=shells[idx]; let s=0;
  for(let j=0;j<shells.length;j++){ const o=shells[j];
    const cnt=o.c-(j===idx?1:0); if(cnt<=0) continue;
    if(o.n>n) continue;                                           // outer shells don't screen
    const sameGroup=(o.n===n)&&((l<=1&&o.l<=1)||(o.l===l&&l>=2)); // (ns,np) form one group; d,f their own
    if(o.n===n&&!sameGroup){ if(o.l>l) continue;                  // same-n higher-l doesn't screen s,p
      s+=cnt*(l>=2?1.0:0.35); continue; }                         // d/f: same-n s,p screen fully
    if(sameGroup) s+=cnt*(n===1?0.30:0.35);
    else if(o.n===n-1) s+=cnt*(l<=1?0.85:1.0);
    else s+=cnt*1.0;
  }
  return Math.max(0.6, Z-s);
}

const GRAV_TH=1/(2-Math.pow(2,1/3)), GRAV_CS=[GRAV_TH/2,(1-GRAV_TH)/2,(1-GRAV_TH)/2,GRAV_TH/2], GRAV_DS=[GRAV_TH,1-2*GRAV_TH,GRAV_TH,0];

function gwPetersRates(a,e,M,c5){
  const e2=e*e, om2=1-e2;
  const da=-(64/5)*(M/c5)/(a*a*a*Math.pow(om2,3.5))*(1+73/24*e2+37/96*e2*e2);
  const de=-(304/15)*e*(M/c5)/(a*a*a*a*Math.pow(om2,2.5))*(1+121/304*e2);
  return [da,de];
}

function gwMergerTime(a0,e0,M,c5){          // numeric — the honest general-e answer
  let a=a0,e=e0,t=0;
  for(let i=0;i<20000&&a>12/Math.pow(c5,0.4);i++){
    const [da,de]=gwPetersRates(a,e,M,c5);
    const h=Math.min(0.5,-0.004*a/da); a+=da*h; e=Math.max(0,e+de*h); t+=h;
    if(a<=0.09) break;
  }
  return t;
}

function gravAccel(B,ax,ay){
  const n=B.length; for(let i=0;i<n;i++){ ax[i]=0; ay[i]=0; }
  for(let i=0;i<n;i++)for(let j=i+1;j<n;j++){
    const dx=B[j].x-B[i].x, dy=B[j].y-B[i].y, r2=dx*dx+dy*dy, inv=1/(r2*Math.sqrt(r2));
    ax[i]+=B[j].m*dx*inv; ay[i]+=B[j].m*dy*inv;
    ax[j]-=B[i].m*dx*inv; ay[j]-=B[i].m*dy*inv; }
}

const _gAx=[0,0,0],_gAy=[0,0,0];

function gravStep(B,h){
  for(let s=0;s<4;s++){
    for(const b of B){ b.x+=GRAV_CS[s]*b.vx*h; b.y+=GRAV_CS[s]*b.vy*h; }
    if(GRAV_DS[s]){ gravAccel(B,_gAx,_gAy);
      for(let i=0;i<B.length;i++){ B[i].vx+=GRAV_DS[s]*_gAx[i]*h; B[i].vy+=GRAV_DS[s]*_gAy[i]*h; } } }
}

function gravRmin(B){ let r=1e9;
  for(let i=0;i<B.length;i++)for(let j=i+1;j<B.length;j++)
    r=Math.min(r,Math.hypot(B[j].x-B[i].x,B[j].y-B[i].y)); return r; }

function gravInvariants(B){
  let E=0,Lz=0,Px=0,Py=0;
  for(const b of B){ E+=.5*b.m*(b.vx*b.vx+b.vy*b.vy); Lz+=b.m*(b.x*b.vy-b.y*b.vx); Px+=b.m*b.vx; Py+=b.m*b.vy; }
  for(let i=0;i<B.length;i++)for(let j=i+1;j<B.length;j++)
    E-=B[i].m*B[j].m/Math.hypot(B[j].x-B[i].x,B[j].y-B[i].y);
  return {E,Lz,P:Math.hypot(Px,Py)};
}

const QM_N=512, QM_L=80, QM_DX=QM_L/QM_N;

const qmX=i=>-QM_L/2+i*QM_DX, qmK=i=>(i<QM_N/2?i:i-QM_N)*2*Math.PI/QM_L;

function qmFFT(re,im,inv){
  const n=re.length;
  for(let i=1,j=0;i<n;i++){ let bit=n>>1;
    for(;j&bit;bit>>=1) j^=bit; j^=bit;
    if(i<j){ const tr=re[i];re[i]=re[j];re[j]=tr; const ti=im[i];im[i]=im[j];im[j]=ti; } }
  for(let len=2;len<=n;len<<=1){
    const ang=(inv?2:-2)*Math.PI/len, wr=Math.cos(ang), wi=Math.sin(ang);
    for(let i=0;i<n;i+=len){
      let cr=1, ci=0;
      for(let k=0;k<len/2;k++){
        const ur=re[i+k], ui=im[i+k];
        const vr=re[i+k+len/2]*cr-im[i+k+len/2]*ci, vi=re[i+k+len/2]*ci+im[i+k+len/2]*cr;
        re[i+k]=ur+vr; im[i+k]=ui+vi; re[i+k+len/2]=ur-vr; im[i+k+len/2]=ui-vi;
        const ncr=cr*wr-ci*wi; ci=cr*wi+ci*wr; cr=ncr; } } }
  if(inv) for(let i=0;i<n;i++){ re[i]/=n; im[i]/=n; }
}

function qmPropagate(re,im,V,n,dt){
  for(let s=0;s<n;s++){
    for(let i=0;i<QM_N;i++){ const ph=-V[i]*dt/2, c=Math.cos(ph), si=Math.sin(ph);
      const r=re[i]*c-im[i]*si; im[i]=re[i]*si+im[i]*c; re[i]=r; }
    qmFFT(re,im,false);
    for(let i=0;i<QM_N;i++){ const k=qmK(i), ph=-k*k/2*dt, c=Math.cos(ph), si=Math.sin(ph);
      const r=re[i]*c-im[i]*si; im[i]=re[i]*si+im[i]*c; re[i]=r; }
    qmFFT(re,im,true);
    for(let i=0;i<QM_N;i++){ const ph=-V[i]*dt/2, c=Math.cos(ph), si=Math.sin(ph);
      const r=re[i]*c-im[i]*si; im[i]=re[i]*si+im[i]*c; re[i]=r; }
  }
  return [re,im];
}

function qmGaussian(x0,k0,sig){
  const re=new Float64Array(QM_N), im=new Float64Array(QM_N); let nrm=0;
  for(let i=0;i<QM_N;i++){ const g=Math.exp(-((qmX(i)-x0)**2)/(4*sig*sig));
    re[i]=g*Math.cos(k0*qmX(i)); im[i]=g*Math.sin(k0*qmX(i)); nrm+=g*g*QM_DX; }
  const f=1/Math.sqrt(nrm); for(let i=0;i<QM_N;i++){ re[i]*=f; im[i]*=f; }
  return [re,im];
}

function qmHarmonic(om){ const V=new Float64Array(QM_N);
  for(let i=0;i<QM_N;i++) V[i]=0.5*om*om*qmX(i)*qmX(i); return V; }

function qmMoments(re,im){
  let n=0,x=0,x2=0;
  for(let i=0;i<QM_N;i++){ const d=(re[i]*re[i]+im[i]*im[i])*QM_DX, q=qmX(i); n+=d; x+=q*d; x2+=q*q*d; }
  const mx=x/(n||1e-300);
  return {norm:n, x:mx, sigma:Math.sqrt(Math.max(0,x2/(n||1e-300)-mx*mx))};
}

const QCD_HC=0.1973, QCD_AS=0.3, QCD_SIG=0.9, QCD_BRK=1.10, QCD_FM=2.6;

const qcdV=r=>-(4/3)*QCD_AS*QCD_HC/r+QCD_SIG*r;

const qcdAlphaS=Q=>{ const nf=Q<1.27?3:Q<4.18?4:5, L=0.21;                 // 1-loop, threshold-crude (declared)
  return 12*Math.PI/((33-2*nf)*Math.log((Q*Q)/(L*L))); };

function topoHopfPts(th,ph,N,R){
  N=N||160; R=R||1.9; const pts=[];
  for(let k=0;k<N;k++){ const t=k/N*2*Math.PI, z1r=Math.cos(th/2)*Math.cos(t+ph), z1i=Math.cos(th/2)*Math.sin(t+ph), z2r=Math.sin(th/2)*Math.cos(t), z2i=Math.sin(th/2)*Math.sin(t), w=1-z2i;
    pts.push([z1r/w*R, z2r/w*R, z1i/w*R]); }
  return pts;
}

function topoLinkPure(A,B){
  let s=0;
  for(let i=0;i<A.length;i++){
    const a=A[i], a2=A[(i+1)%A.length];
    const vax=a2[0]-a[0], vay=a2[1]-a[1], vaz=a2[2]-a[2];
    const amx=(a[0]+a2[0])/2, amy=(a[1]+a2[1])/2, amz=(a[2]+a2[2])/2;
    for(let j=0;j<B.length;j++){
      const b=B[j], b2=B[(j+1)%B.length];
      const vbx=b2[0]-b[0], vby=b2[1]-b[1], vbz=b2[2]-b[2];
      const rx=amx-(b[0]+b2[0])/2, ry=amy-(b[1]+b2[1])/2, rz=amz-(b[2]+b2[2])/2;
      const rl=Math.hypot(rx,ry,rz);
      const cx=vay*vbz-vaz*vby, cy=vaz*vbx-vax*vbz, cz=vax*vby-vay*vbx;
      s+=(cx*rx+cy*ry+cz*rz)/(rl*rl*rl);
    }
  }
  return s/(4*Math.PI);
}

function topoHopfPair(th1,th2,ph1,ph2,N){
  N=N||240;
  return [topoHopfPts(th1,ph1,N,1.9), topoHopfPts(th2,ph2,N,1.9)];
}

