const CMB_LMAX=12, CMB_D0=1000;

function cmbHash01(seed,l,m,salt=0){
  let x=(seed|0)^Math.imul((l+37)|0,0x9e3779b1)^Math.imul((m+71)|0,0x85ebca6b)^Math.imul((salt+11)|0,0xc2b2ae35);
  x^=x>>>16;x=Math.imul(x,0x7feb352d);x^=x>>>15;x=Math.imul(x,0x846ca68b);x^=x>>>16;
  return ((x>>>0)+.5)/4294967296;
}

function cmbGaussian(seed,l,m){const u=Math.max(1e-12,cmbHash01(seed,l,m,1)),v=cmbHash01(seed,l,m,2);return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);}

const cmbDlOf=(l,low)=>CMB_D0*(l<=3?low:1);

const cmbClOf=(l,low)=>2*Math.PI*cmbDlOf(l,low)/(l*(l+1));

function cmbCoeffKey(l,m){return `${l}:${m}`;}

function cmbCoeffsPure(seed,lmax,low){
  const out=new Map();for(let l=2;l<=lmax;l++){const s=Math.sqrt(cmbClOf(l,low));for(let m=-l;m<=l;m++)out.set(cmbCoeffKey(l,m),s*cmbGaussian(seed,l,m));}return out;
}

function cmbSumL(coeff,l,th,ph){let s=0;for(let m=-l;m<=l;m++)s+=(coeff.get(cmbCoeffKey(l,m))||0)*shY(l,m,th,ph);return s;}

function cmbDl(coeff,l){let p=0;for(let m=-l;m<=l;m++){const a=coeff.get(cmbCoeffKey(l,m))||0;p+=a*a;}return l*(l+1)*p/((2*l+1)*2*Math.PI);}

function cmbMaskAllows(th,maskDeg=state.cmbMaskDeg??0){return Math.abs(Math.PI/2-th)>=maskDeg*Math.PI/180;}

function cmbRecoverPure(coeff,lmax,maskDeg,Nt,Np){
  const modes=[];for(let l=2;l<=lmax;l++)for(let m=-l;m<=l;m++)modes.push({l,m,key:cmbCoeffKey(l,m),a:coeff.get(cmbCoeffKey(l,m))||0});
  const sum=new Float64Array(modes.length),basis=new Float64Array(modes.length),fs=Math.max(.05,1-Math.sin(maskDeg*Math.PI/180)),dth=Math.PI/Nt,dph=2*Math.PI/Np;
  for(let i=0;i<Nt;i++){const th=(i+.5)*dth;if(!cmbMaskAllows(th,maskDeg))continue;const w=Math.sin(th)*dth*dph;
    for(let j=0;j<Np;j++){const ph=(j+.5)*dph;let T=0;for(let q=0;q<modes.length;q++){const h=shY(modes[q].l,modes[q].m,th,ph);basis[q]=h;T+=modes[q].a*h;}const s=T*w/fs;for(let q=0;q<modes.length;q++)sum[q]+=s*basis[q];}}
  return new Map(modes.map((q,i)=>[q.key,sum[i]]));
}

