const photonSNR=(N,B,t)=>{ const S=N*t, V=(N+B)*t; return V>0?S/Math.sqrt(V):0; };

const photonTimeFor=(snr,N,B)=>N>0?snr*snr*(N+B)/(N*N):Infinity;

const photonFluxOfMag=m=>photonF0()*Math.pow(10,-0.4*m);

const photonMagOfFlux=f=>-2.5*Math.log10(Math.max(1e-300,f)/photonF0());

function photonLimitingMag(D,lam,t,snr,B){
  const A=photonArea(D), E=photonEnergy(lam);
  /* N t^2 ... solve snr^2 (N+B) t = N^2 t^2 for N: N^2 t - snr^2 N - snr^2 B = 0 */
  const a=t, b=-snr*snr, c=-snr*snr*B;
  const N=(-b+Math.sqrt(b*b-4*a*c))/(2*a);
  return photonMagOfFlux(N*E/A);
}

function photonRng(seed){
  let a=seed|0;
  return ()=>{ a=(a+0x6D2B79F5)|0;
    let t=Math.imul(a^(a>>>15),1|a);
    t=(t+Math.imul(t^(t>>>7),61|t))^t;
    return ((t^(t>>>14))>>>0)/4294967296; };
}

function photonPoisson(lambda,rnd){
  if(lambda<=0) return 0;
  if(lambda<30){ const L=Math.exp(-lambda); let k=0,p=1;
    do{ k++; p*=rnd(); }while(p>L); return k-1; }
  const u=Math.max(1e-12,rnd()), v=rnd();
  const z=Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);
  return Math.max(0,Math.round(lambda+Math.sqrt(lambda)*z));
}

const RES_AS=206264.80624709636;

function resBesselJ1(x){
  const a=Math.abs(x);
  if(a<8){ const y=x*x;
    const p=x*(72362614232+y*(-7895059235+y*(242396853.1+y*(-2972611.439+y*(15704.48260+y*(-30.16036606))))));
    const q=144725228442+y*(2300535178+y*(18583304.74+y*(99447.43394+y*(376.9991397+y))));
    return p/q; }
  const z=8/a, y=z*z, xx=a-2.356194491;
  const p1=1+y*(0.183105e-2+y*(-0.3516396496e-4+y*(0.2457520174e-5+y*(-0.240337019e-6))));
  const p2=0.04687499995+y*(-0.2002690873e-3+y*(0.8449199096e-5+y*(-0.88228987e-6+y*0.105787412e-6)));
  const r=Math.sqrt(0.636619772/a)*(Math.cos(xx)*p1-z*Math.sin(xx)*p2);
  return x<0?-r:r;
}

const RES_J1_ZERO=(()=>{ let lo=3.5,hi=4.2;
  for(let i=0;i<200;i++){ const m=(lo+hi)/2;
    if(resBesselJ1(lo)*resBesselJ1(m)<=0) hi=m; else lo=m; }
  return (lo+hi)/2; })();

const RES_RAYLEIGH_K=RES_J1_ZERO/Math.PI;

const resRayleigh=(lam,D)=>RES_RAYLEIGH_K*lam/D;

const resAiry=x=>{ const a=Math.abs(x); if(a<1e-9) return 1; const t=2*resBesselJ1(x)/x; return t*t; };

const resAiryX=(theta,lam,D)=>Math.PI*D*Math.sin(theta)/lam;

const resApertureFor=(theta,lam)=>RES_RAYLEIGH_K*lam/Math.max(1e-300,theta);

const resDawes=D=>(116/(D*1000))/RES_AS;

