const PHOT_L0=3.0128e28;

const PHOT_LSUN=3.828e26;

const PHOT_PC=3.0856775814913673e16;

const PHOT_ERG_W=1e-7;

const photAbsolute=Lw=>-2.5*Math.log10(Lw/PHOT_L0);

const photModulus=dm=>5*Math.log10(dm/(10*PHOT_PC));

const photFlux=(Lw,dm)=>Lw/(4*Math.PI*dm*dm);

const photApparent=(Lw,dm)=>photAbsolute(Lw)+photModulus(dm);

