function hzGyroPair(o){ o=o||{};
  const bmag=o.B||1;
  const qm=o.qm||1.75882e11;
  const eps0=o.eps0||1e-6;
  const turns=o.turns||40;
  const perTurn=o.perTurn||200;
  const w=qm*bmag;
  const dt=2*Math.PI/(w*perTurn);
  const push=(x,vel)=>{
    const tn=qm*bmag*dt/2;
    const sn=2*tn/(1+tn*tn);
    const vx=vel[0];
    const vy=vel[1];
    const vpx=vx+vy*tn;
    const vpy=vy-vx*tn;
    const nvx=vx+vpy*sn;
    const nvy=vy-vpx*sn;
    return [[x[0]+nvx*dt, x[1]+nvy*dt, x[2]+vel[2]*dt],[nvx,nvy,vel[2]]]; };
  let xa=[0,0,0];
  let va=[1e5,0,0];
  let xb=[eps0,0,0];
  let vb=[1e5,0,0];
  let mx=0;
  let mn=Infinity;
  for(let i=0;i<turns*perTurn;i++){
    const ra=push(xa,va);
    const rb=push(xb,vb);
    xa=ra[0]; va=ra[1]; xb=rb[0]; vb=rb[1];
    const d=Math.hypot(xa[0]-xb[0],xa[1]-xb[1],xa[2]-xb[2]);
    if(d>mx)mx=d; if(d<mn)mn=d; }
  return {rate:w, eps0:eps0, max_separation:mx, min_separation:mn,
          growth:mx/eps0, turns, horizon:Infinity}; }

const CK_S=10, CK_R=28, CK_B=8/3;

const CK_REF=0.9056;

function ckF(x,y,z){ return [CK_S*(y-x), x*(CK_R-z)-y, x*y-CK_B*z]; }

function ckRK(s,h){
  const k1=ckF(s[0],s[1],s[2]);
  const k2=ckF(s[0]+h/2*k1[0],s[1]+h/2*k1[1],s[2]+h/2*k1[2]);
  const k3=ckF(s[0]+h/2*k2[0],s[1]+h/2*k2[1],s[2]+h/2*k2[2]);
  const k4=ckF(s[0]+h*k3[0],s[1]+h*k3[1],s[2]+h*k3[2]);
  return [s[0]+h/6*(k1[0]+2*k2[0]+2*k3[0]+k4[0]),
          s[1]+h/6*(k1[1]+2*k2[1]+2*k3[1]+k4[1]),
          s[2]+h/6*(k1[2]+2*k2[2]+2*k3[2]+k4[2])]; }

function ckMaxima(o){
  o=o||{};
  const h=o.h||0.004;
  const want=Math.max(200,o.maxima||40000);
  const cap=o.cap||60000000;
  let s=o.seed?o.seed.slice():[1,1,1];
  const warm=Math.round((o.warmup==null?120:o.warmup)/h);
  for(let i=0;i<warm;i++) s=ckRK(s,h);
  const z=[];
  const t=[];
  let pz=s[2];
  let ppz=null;
  let clock=0;
  for(let i=0;i<cap&&z.length<want;i++){
    const n=ckRK(s,h);
    clock+=h;
    if(ppz!==null&&pz>ppz&&pz>n[2]){
      /* the vertex of the parabola through (ppz, pz, n) */
      const den=ppz-2*pz+n[2];
      const off=(den!==0)?0.5*(ppz-n[2])/den:0;
      z.push(pz-0.125*(ppz-n[2])*off);
      t.push(clock-h+off*h);
    }
    ppz=pz; pz=n[2]; s=n;
  }
  let sum=0;
  for(let i=1;i<t.length;i++) sum+=t[i]-t[i-1];
  const meanT=(t.length>1)?sum/(t.length-1):NaN;
  let v=0;
  for(let i=1;i<t.length;i++){ const d=t[i]-t[i-1]-meanT; v+=d*d; }
  return {z:z, t:t, meanT:meanT,
          sdT:(t.length>2)?Math.sqrt(v/(t.length-2)):NaN, h:h}; }

function ckMapExponent(z,K){
  const k=Math.max(4,K||40);
  const p=[];
  for(let i=0;i<z.length-1;i++) p.push([z[i],z[i+1]]);
  p.sort((a,b)=>a[0]-b[0]);
  const m=2*k+1;
  let acc=0;
  let n=0;
  let lo=Infinity;
  let hi=-Infinity;
  let below=0;
  const slopes=[];
  for(let i=k;i<p.length-k;i++){
    let sx=0, sy=0, sxx=0, sxy=0;
    for(let j=i-k;j<=i+k;j++){ sx+=p[j][0]; sy+=p[j][1]; sxx+=p[j][0]*p[j][0]; sxy+=p[j][0]*p[j][1]; }
    const den=m*sxx-sx*sx;
    if(!(Math.abs(den)>1e-12)) continue;
    const sl=(m*sxy-sx*sy)/den;
    if(!(Math.abs(sl)>0)) continue;
    const l=Math.log(Math.abs(sl));
    if(l<lo) lo=l;
    if(l>hi) hi=l;
    if(Math.abs(sl)<1) below++;
    acc+=l; n++;
    slopes.push([p[i][0],sl]);
  }
  return {lambda:acc/n, n:n, ln_min:lo, ln_max:hi,
          fraction_contracting:below/n, slopes:slopes, pairs:p}; }

function ckBridge(o){
  o=o||{};
  const M=ckMaxima(o);
  const E=ckMapExponent(M.z,o.neighbours||40);
  const flow=E.lambda/M.meanT;
  return {mean_return_time:M.meanT, return_time_sd:M.sdT,
          lambda_per_iteration:E.lambda, lambda_per_time:flow,
          reference:CK_REF, relative_error:flow/CK_REF-1,
          maxima:M.z.length, slope_points:E.n,
          ln_slope_min:E.ln_min, ln_slope_max:E.ln_max,
          fraction_contracting:E.fraction_contracting,
          z:M.z, t:M.t, slopes:E.slopes, pairs:E.pairs, h:M.h}; }

const CK_TIME_UNITS=Object.freeze(['s','ms','us','ns','yr','Gyr','Myr','day','time','tau','volume time']);

function ckHasClock(spec){
  if(!spec) return {clock:false, carriers:[]};
  const carriers=[];
  for(const o of (spec.outputs||[])) if(CK_TIME_UNITS.indexOf(o.unit)>=0) carriers.push('out '+o.name+' ['+o.unit+']');
  for(const i of (spec.inputs||[]))  if(CK_TIME_UNITS.indexOf(i.unit)>=0) carriers.push('in '+i.name+' ['+i.unit+']');
  return {clock:carriers.length>0, carriers:carriers}; }

