const CQ_H=6.62607015e-34;

const CQ_E=1.602176634e-19;

const CQ_U=1.66053906660e-27;

const CQ_M4=4.002602*CQ_U;

const CQ_M3=3.0160293*CQ_U;

const CQ_CORE=1e-10;

const cqKappa4=()=>CQ_H/CQ_M4;

const cqKappa3=()=>CQ_H/(2*CQ_M3);

const cqPhi0=()=>CQ_H/(2*CQ_E);

const cqFeynman=(omega,kappa)=>2*omega/kappa;

const cqAbrikosov=(B)=>B/cqPhi0();

const cqRotationPerTesla=(kappa)=>kappa/(2*cqPhi0());

const cqSpacing=(n)=>Math.sqrt(2/(Math.sqrt(3)*n));

const cqOmegaC1=(kappa,R,a)=>(kappa/(2*Math.PI*R*R))*Math.log(R/(a||CQ_CORE));

const cqRingSpeed=(kappa,R,a)=>(kappa/(4*Math.PI*R))*(Math.log(8*R/(a||CQ_CORE))-0.5);

function cqLattice(omega,R,kappa){
  const k=kappa||cqKappa4();
  const n=cqFeynman(omega,k);
  const a=cqSpacing(n);
  const pts=[];
  const M=Math.ceil(R/a)+2;
  for(let i=-M;i<=M;i++){
    for(let j=-M;j<=M;j++){
      const x=a*(i+0.5*j);
      const y=a*(Math.sqrt(3)/2)*j;
      if(x*x+y*y<=R*R) pts.push([x,y]);
    }
  }
  return {pts:pts, density:n, spacing:a, kappa:k, R:R, omega:omega}; }

function cqVTheta(pts,r,kappa,nAng){
  const k=kappa||cqKappa4();
  const N=nAng||720;
  let s=0;
  for(let q=0;q<N;q++){
    const th=2*Math.PI*q/N;
    const px=r*Math.cos(th);
    const py=r*Math.sin(th);
    let vx=0;
    let vy=0;
    for(let i=0;i<pts.length;i++){
      const dx=px-pts[i][0];
      const dy=py-pts[i][1];
      const d2=dx*dx+dy*dy;
      if(d2<1e-24) continue;
      vx-=dy/d2; vy+=dx/d2;
    }
    vx*=k/(2*Math.PI); vy*=k/(2*Math.PI);
    s+=(-vx*Math.sin(th)+vy*Math.cos(th));
  }
  return s/N; }

function cqProfile(L,frac,nAng){
  const r=frac*L.R;
  let N=0;
  for(let i=0;i<L.pts.length;i++){
    const p=L.pts[i];
    if(p[0]*p[0]+p[1]*p[1]<r*r) N++;
  }
  const ideal=L.density*Math.PI*r*r;
  const v=cqVTheta(L.pts,r,L.kappa,nAng);
  const ampere=L.kappa*N/(2*Math.PI*r);
  const solid=L.omega*r;
  return {r:r, enclosed:N, ideal:ideal, v:v, ampere:ampere, solid:solid,
          ampere_residual:Math.abs(v/ampere-1),
          solid_ratio:v/solid,
          counting:Math.abs(N-ideal)/ideal}; }

const LM_C=299792458;

const LM_G=6.67430e-11;

const LM_HBAR=1.054571817e-34;

const LM_KB=1.380649e-23;

const LM_MPC=3.0856775814913673e22;

const LM_GLY=9.4607304725808e24;

const LM_PARTICLE_GLY=46.5;

const lmPlanckArea=()=>LM_HBAR*LM_G/(LM_C*LM_C*LM_C);

const lmPlanckDensity=()=>Math.pow(LM_C,5)/(LM_HBAR*LM_G*LM_G);

const lmLambda=(H0kms,omegaL)=>{ const H=H0kms*1e3/LM_MPC; return 3*omegaL*H*H/(LM_C*LM_C); };

const lmHubbleLength=(H0kms)=>LM_C/(H0kms*1e3/LM_MPC);

const lmDeSitter=(Lam)=>Math.sqrt(3/Lam);

const lmArea=(R)=>4*Math.PI*R*R;

const lmEntropy=(R)=>lmArea(R)*LM_KB/(4*lmPlanckArea());

const lmBits=(R)=>lmEntropy(R)/(LM_KB*Math.LN2);

const lmGibbonsHawking=(R)=>LM_HBAR*LM_C/(2*Math.PI*LM_KB*R);

const lmVacuumDensity=(Lam)=>Lam*LM_C*LM_C/(8*Math.PI*LM_G);

const lmVacuumEnergyDensity=(Lam)=>lmVacuumDensity(Lam)*LM_C*LM_C;

const lmPlanckRatio=(Lam)=>lmVacuumDensity(Lam)/lmPlanckDensity();

const lmLambdaInPlanckUnits=(Lam)=>Lam*lmPlanckArea();

function lmHorizons(H0kms,omegaL){
  const Lam=lmLambda(H0kms,omegaL);
  const rows=[
    {id:'hubble',   R:lmHubbleLength(H0kms)},
    {id:'desitter', R:lmDeSitter(Lam)},
    {id:'particle', R:LM_PARTICLE_GLY*LM_GLY}
  ];
  for(const r of rows){ r.gly=r.R/LM_GLY; r.bits=lmBits(r.R); r.T=lmGibbonsHawking(r.R); }
  let lo=Infinity;
  let hi=0;
  for(const r of rows){ if(r.bits<lo) lo=r.bits; if(r.bits>hi) hi=r.bits; }
  return {rows:rows, spread:hi/lo, lambda:Lam}; }

