const HR_FCORE=0.1;

const HR_KAPPA=0.034;

const hrEddington=m=>4*Math.PI*HR_G*m*HR_MSUN*HR_C/HR_KAPPA/HR_LSUN;

const HR_EDD_FRACTION=0.833;

function hrLuminosity(m){
  if(!(m>0)) return 0;
  if(m<0.43) return 0.23*Math.pow(m,2.3);
  if(m<2)    return Math.pow(m,4);
  if(m<55)   return 1.4*Math.pow(m,3.5);
  return HR_EDD_FRACTION*hrEddington(m);
}

function hrExponent(m){
  const h=1e-4;
  const a=hrLuminosity(m*(1-h)), b=hrLuminosity(m*(1+h));
  if(!(a>0&&b>0)) return NaN;
  return (Math.log(b)-Math.log(a))/(Math.log(m*(1+h))-Math.log(m*(1-h)));
}

function hrRadius(m){ return (m<1)?Math.pow(m,0.8):Math.pow(m,0.57); }

function hrTemperature(m){
  const R=hrRadius(m);
  return HR_TSUN*Math.pow(hrLuminosity(m)/(R*R),0.25);
}

function hrLifetime(m){
  const L=hrLuminosity(m);
  if(!(L>0)) return Infinity;
  return HR_EPS*HR_FCORE*m*HR_MSUN*HR_C*HR_C/(L*HR_LSUN);
}

const hrLifetimeGyr=m=>hrLifetime(m)/HR_GYR;

function hrTurnoff(ageGyr){
  if(!(ageGyr>0)) return 200;
  let lo=0.05, hi=200;
  for(let i=0;i<200;i++){
    const mid=Math.sqrt(lo*hi);
    if(hrLifetimeGyr(mid)>ageGyr) lo=mid; else hi=mid;
  }
  return Math.sqrt(lo*hi);
}

function hrRemnant(m){
  if(m<8) return 0.109*m+0.394;
  if(m<25) return 1.4;
  return 0.1*m;
}

function hrIMF(m,kind){
  if(kind==='kroupa'){
    if(m<0.08) return 0;
    if(m<0.5)  return Math.pow(m/0.5,-1.3)*Math.pow(0.5,-2.3);
    return Math.pow(m,-2.3);
  }
  return Math.pow(m,-2.35);
}

function hrMassToLight(ageGyr,opt){
  const o=opt||{};
  const kind=o.imf||'salpeter';
  const lo=(o.m_min==null?0.1:o.m_min);
  const hi=(o.m_max==null?100:o.m_max);
  const N=(o.samples==null?4000:Math.round(o.samples));
  const mto=hrTurnoff(ageGyr);
  let mass=0, light=0, massAlive=0, nAlive=0, nDead=0;
  const dx=(Math.log(hi)-Math.log(lo))/N;
  for(let i=0;i<N;i++){
    const x=Math.log(lo)+dx*(i+0.5);
    const m=Math.exp(x);
    const w=hrIMF(m,kind)*m*dx;
    if(m<=mto){ mass+=w*m; massAlive+=w*m; light+=w*hrLuminosity(m); nAlive+=w; }
    else { mass+=w*hrRemnant(m); nDead+=w; }
  }
  return {mass_to_light:(light>0)?mass/light:Infinity,
    turnoff:mto, mass_total:mass, light_total:light,
    mass_in_living_stars:massAlive, remnant_mass_fraction:(mass>0)?(mass-massAlive)/mass:0,
    number_alive:nAlive, number_dead:nDead};
}

function hrMassToLightNoRemnants(ageGyr,opt){
  const r=hrMassToLight(ageGyr,opt);
  return (r.light_total>0)?r.mass_in_living_stars/r.light_total:Infinity;
}

function hrPopulation(n,kind,seed){
  const out=[];
  const N=Math.max(1,Math.round(n));
  let s=(seed==null?20260902:seed)>>>0;
  const rnd=()=>{ s=(Math.imul(s,1103515245)+12345)>>>0; return (s&0x7fffffff)/0x7fffffff; };
  const lo=0.1, hi=100;
  const a=(kind==='kroupa')?2.3:2.35;
  for(let i=0;i<N;i++){
    const u=1e-6+(1-2e-6)*rnd();
    /* inverse CDF of a single power law between lo and hi */
    const p=1-a;
    const m=Math.pow(Math.pow(lo,p)+u*(Math.pow(hi,p)-Math.pow(lo,p)),1/p);
    out.push(m);
  }
  out.sort((x,y)=>x-y);
  return out;
}

function hrSunCheck(){
  return {luminosity:hrLuminosity(1), lifetime_gyr:hrLifetimeGyr(1),
    temperature:hrTemperature(1), radius:hrRadius(1),
    eddington_ratio:hrLuminosity(1)/hrEddington(1)};
}

function hrGiantLight(ageGyr,windowFraction,brightening,opt){
  const o=opt||{};
  const kind=o.imf||'salpeter';
  const lo=(o.m_min==null?0.1:o.m_min);
  const hi=(o.m_max==null?100:o.m_max);
  const N=(o.samples==null?4000:Math.round(o.samples));
  const mto=hrTurnoff(ageGyr);
  const dx=(Math.log(hi)-Math.log(lo))/N;
  let msLight=0;
  for(let i=0;i<N;i++){
    const m=Math.exp(Math.log(lo)+dx*(i+0.5));
    if(m<=mto) msLight+=hrIMF(m,kind)*m*dx*hrLuminosity(m);
  }
  const w=(windowFraction||0)*hrLifetimeGyr(mto);
  if(!(w>0)||!(brightening>0)) return {ms_light:msLight, giant_light:0, ratio:0, mass_window_top:mto};
  const mHi=hrTurnoff(Math.max(1e-9,ageGyr-w));
  let nG=0;
  for(let i=0;i<N;i++){
    const m=Math.exp(Math.log(lo)+dx*(i+0.5));
    if(m>mto&&m<=mHi) nG+=hrIMF(m,kind)*m*dx;
  }
  const gl=nG*brightening*hrLuminosity(mto);
  return {ms_light:msLight, giant_light:gl, ratio:(msLight>0)?gl/msLight:Infinity,
    mass_window_top:mHi, number_of_giants:nG, window_gyr:w};
}

const GR_G=6.67430e-11;

const GR_MSUN=1.98892e30;

const GR_KPC=3.0856775814913673e19;

const GR_PC=3.0856775814913673e16;

const GR_C=299792458;

const GR_MPC=3.0856775814913673e22;

const GR_A0=1.2e-10;

const GR_HELIUM=1.33;

function grBessI0(x){
  const a=Math.abs(x);
  if(a<3.75){ const y=(x/3.75)*(x/3.75);
    return 1+y*(3.5156229+y*(3.0899424+y*(1.2067492+y*(0.2659732+y*(0.360768e-1+y*0.45813e-2))))); }
  const y=3.75/a;
  return Math.exp(a)/Math.sqrt(a)*(0.39894228+y*(0.1328592e-1+y*(0.225319e-2+y*(-0.157565e-2
    +y*(0.916281e-2+y*(-0.2057706e-1+y*(0.2635537e-1+y*(-0.1647633e-1+y*0.392377e-2))))))));
}

function grBessI1(x){
  const a=Math.abs(x);
  let ans;
  if(a<3.75){ const y=(x/3.75)*(x/3.75);
    ans=a*(0.5+y*(0.87890594+y*(0.51498869+y*(0.15084934+y*(0.2658733e-1+y*(0.301532e-2+y*0.32411e-3)))))); }
  else { const y=3.75/a;
    let t=0.2282967e-1+y*(-0.2895312e-1+y*(0.1787654e-1-y*0.420059e-2));
    t=0.39894228+y*(-0.3988024e-1+y*(-0.362018e-2+y*(0.163801e-2+y*(-0.1031555e-1+y*t))));
    ans=t*Math.exp(a)/Math.sqrt(a); }
  return x<0?-ans:ans;
}

function grBessK0(x){
  if(x<=2){ const y=x*x/4;
    return -Math.log(x/2)*grBessI0(x)+(-0.57721566+y*(0.42278420+y*(0.23069756+y*(0.3488590e-1
      +y*(0.262698e-2+y*(0.10750e-3+y*0.74e-5)))))); }
  const y=2/x;
  return Math.exp(-x)/Math.sqrt(x)*(1.25331414+y*(-0.7832358e-1+y*(0.2189568e-1+y*(-0.1062446e-1
    +y*(0.587872e-2+y*(-0.251540e-2+y*0.53208e-3))))));
}

function grBessK1(x){
  if(x<=2){ const y=x*x/4;
    return Math.log(x/2)*grBessI1(x)+(1/x)*(1+y*(0.15443144+y*(-0.67278579+y*(-0.18156897
      +y*(-0.1919402e-1+y*(-0.110404e-2+y*(-0.4686e-4))))))); }
  const y=2/x;
  return Math.exp(-x)/Math.sqrt(x)*(1.25331414+y*(0.23498619+y*(-0.3655620e-1+y*(0.1504268e-1
    +y*(-0.780353e-2+y*(0.325614e-2+y*(-0.68245e-3)))))));
}

function grWronskian(x){ return grBessI1(x)*grBessK0(x)+grBessI0(x)*grBessK1(x); }

function grBesselResidual(x){ return Math.abs(grWronskian(x)*x-1); }

function grDiscV2(r,S0,Rd){
  const y=r/(2*Rd);
  if(!(y>1e-9)) return 0;
  return 4*Math.PI*GR_G*S0*Rd*y*y*(grBessI0(y)*grBessK0(y)-grBessI1(y)*grBessK1(y));
}

const grDiscSigma0=(Md,Rd)=>Md/(2*Math.PI*Rd*Rd);

const grDiscV=(r,S0,Rd)=>Math.sqrt(Math.max(0,grDiscV2(r,S0,Rd)));

function grDiscPeak(S0,Rd){
  let lo=0.05*Rd, hi=8*Rd;
  const phi=(Math.sqrt(5)-1)/2;
  let a=hi-phi*(hi-lo), b=lo+phi*(hi-lo);
  for(let i=0;i<200;i++){
    if(grDiscV2(a,S0,Rd)>grDiscV2(b,S0,Rd)){ hi=b; b=a; a=hi-phi*(hi-lo); }
    else { lo=a; a=b; b=lo+phi*(hi-lo); }
  }
  const r=0.5*(lo+hi);
  return {radius:r, radius_over_Rd:r/Rd, speed:Math.sqrt(Math.max(0,grDiscV2(r,S0,Rd)))};
}

const grKeplerV=(r,M)=>Math.sqrt(GR_G*M/r);

function grGasV2(r,Mg,Rg){ return grDiscV2(r,grDiscSigma0(Mg,Rg),Rg); }

function grNFWMass(r,rhos,rs){
  const x=r/rs;
  return 4*Math.PI*rhos*rs*rs*rs*(Math.log(1+x)-x/(1+x));
}

function grNFWV(r,rhos,rs){ return Math.sqrt(GR_G*grNFWMass(r,rhos,rs)/r); }

function grIsoV(r,rho0,rc){
  if(!(r>0)) return 0;
  return Math.sqrt(4*Math.PI*GR_G*rho0*rc*rc*(1-(rc/r)*Math.atan(r/rc)));
}

const grIsoAsymptote=(rho0,rc)=>Math.sqrt(4*Math.PI*GR_G*rho0*rc*rc);

