function xpHabitableZone(lum){
  const s=Math.sqrt(lum/XP_LSUN);
  return {recent_venus:XP_HZ.recentVenus*s, inner:XP_HZ.runawayGreenhouse*s,
          outer:XP_HZ.maxGreenhouse*s, early_mars:XP_HZ.earlyMars*s, scale:s}; }

function xpZoneStanding(aAU,hz){
  return {recent_venus:aAU>=hz.recent_venus, conservative:aAU>=hz.inner&&aAU<=hz.outer,
          optimistic:aAU>=hz.recent_venus&&aAU<=hz.early_mars,
          too_hot:aAU<hz.recent_venus, too_cold:aAU>hz.early_mars}; }

const xpInZone=(aAU,hz)=>aAU>=hz.inner&&aAU<=hz.outer;

