function xpSystem(id){
  const S=XP_SYSTEMS.filter(x=>x.id===id)[0];
  if(!S) return null;
  const gm=XP_G*S.ms;
  const a=xpSemiMajor(S.P,gm+XP_G*S.mp);
  const lum=xpLuminosity(S.rs,S.ts);
  const hz=xpHabitableZone(lum);
  return {id:S.id, t:S.t, note:S.note,
    period_days:S.P/XP_DAY, a_m:a, a_au:a/XP_AU,
    depth:xpDepth(S.rp,S.rs), depth_ppm:1e6*xpDepth(S.rp,S.rs),
    duration_h:xpDuration(S.P,a,S.rs,S.rp,0)/3600,
    probability:xpTransitProbability(S.rs,S.rp,a),
    K:xpRadialVelocity(S.P,S.mp,S.ms,Math.PI/2,S.ecc),
    T_eq:xpEquilibriumT(S.ts,S.rs,a,0),
    luminosity:lum, luminosity_sun:lum/XP_LSUN,
    hz:hz, in_zone:xpInZone(a/XP_AU,hz),
    zone:xpZoneStanding(a/XP_AU,hz), flux_earth:xpFluxEarth(lum,a/XP_AU),
    rp:S.rp, rs:S.rs, mp:S.mp, ms:S.ms, ts:S.ts, ecc:S.ecc}; }

function xpLightCurve(S,b,n){
  const N=n||240;
  const out=[];
  const a=S.a_m;
  const halfPhase=Math.asin(Math.min(1,Math.sqrt(Math.max(0,(S.rs+S.rp)*(S.rs+S.rp)-(b||0)*(b||0)*S.rs*S.rs))/a))/Math.PI;
  for(let i=0;i<N;i++){
    const ph=-1.6*halfPhase+3.2*halfPhase*(i/(N-1));
    const x=a*Math.sin(2*Math.PI*ph);
    const y=(b||0)*S.rs;
    const sep=Math.hypot(x,y);
    out.push([ph, 1-xpOverlap(sep,S.rs,S.rp)]);
  }
  return out; }

function xpOverlap(d,R,r){
  if(d>=R+r) return 0;
  if(d<=R-r) return (r*r)/(R*R);
  const d2=d*d, R2=R*R, r2=r*r;
  const a1=Math.acos(Math.max(-1,Math.min(1,(d2+R2-r2)/(2*d*R))));
  const a2=Math.acos(Math.max(-1,Math.min(1,(d2+r2-R2)/(2*d*r))));
  const area=R2*(a1-Math.sin(2*a1)/2)+r2*(a2-Math.sin(2*a2)/2);
  return area/(Math.PI*R2); }

const QR_H=6.62607015e-34, QR_HBAR=1.054571817e-34, QR_KB=1.380649e-23;

const QR_C=299792458, QR_ME=9.1093837015e-31, QR_MU=1.66053906660e-27;

const QR_E=1.602176634e-19, QR_EPS0=8.8541878128e-12;

const QR_BEC=2.612375348685488;

const qrLambdaT=(m,T)=>QR_H/Math.sqrt(2*Math.PI*m*QR_KB*T);

const qrDegeneracy=(n,m,T)=>n*Math.pow(qrLambdaT(m,T),3);

const qrFermiEnergy=(n,m)=>{ const kF=Math.pow(3*Math.PI*Math.PI*n,1/3);
  return QR_HBAR*QR_HBAR*kF*kF/(2*m); };

const qrFermiT=(n,m)=>qrFermiEnergy(n,m)/QR_KB;

const qrFrozen=(f,T)=>QR_H*f/(QR_KB*T);

const qrFreezeFrequency=T=>QR_KB*T/QR_H;

const qrCyclotron=(B,m)=>QR_E*B/m;

const qrLandau=(B,m,T)=>QR_HBAR*qrCyclotron(B,m)/(QR_KB*T);

const qrAction=(m,L,v)=>m*L*v/QR_HBAR;

const qrTunnel=(m,V,E,w)=>{ const d=V-E; if(d<=0) return 0;
  return 2*w*Math.sqrt(2*m*d)/QR_HBAR; };

const qrTransmission=(m,V,E,w)=>Math.exp(-qrTunnel(m,V,E,w));

const qrCasimir=d=>Math.PI*Math.PI*QR_HBAR*QR_C/(240*Math.pow(d,4));

const qrCompton=m=>QR_H/(m*QR_C);

const qrBecT=(n,m)=>Math.pow(n/QR_BEC,2/3)*2*Math.PI*QR_HBAR*QR_HBAR/(m*QR_KB);

function qrCriteria(i){
  const m=i.mass, T=i.temperature, n=i.number_density, L=i.size,
        f=i.frequency, B=i.field, v=i.speed;
  const lam=qrLambdaT(m,T);
  const out=[];
  const add=(id,t,value,fires,unlocks)=>out.push({id,t,value,fires,unlocks});
  add('degeneracy',['wavefunctions overlap','волновые функции перекрываются','Wellenfunktionen ueberlappen'],
      qrDegeneracy(n,m,T), qrDegeneracy(n,m,T)>=1,
      ['Bose-Einstein condensation','Fermi degeneracy','superfluidity','exchange forces']);
  add('condensation',['an ideal Bose gas condenses','идеальный бозе-газ конденсируется','ein ideales Bose-Gas kondensiert'],
      qrDegeneracy(n,m,T)/QR_BEC, qrDegeneracy(n,m,T)>=QR_BEC,
      ['Bose-Einstein condensate','superfluid helium','the lambda point']);
  add('fermi',['the exclusion principle sets the energy','принцип запрета задаёт энергию','das Ausschlussprinzip setzt die Energie'],
      T/qrFermiT(n,m), T/qrFermiT(n,m)<=1,
      ['metallic conduction','white-dwarf support','neutron degeneracy','Pauli paramagnetism']);
  add('frozen',['the mode is frozen out','мода заморожена','die Mode ist eingefroren'],
      qrFrozen(f,T), qrFrozen(f,T)>=1,
      ['no ultraviolet catastrophe','Einstein and Debye heat capacity','a blackbody with a peak']);
  add('classical',['the action is many quanta','действие — много квантов','die Wirkung ist viele Quanten'],
      qrAction(m,L,v), qrAction(m,L,v)<=1,
      ['interference of the whole object','matter-wave diffraction','no classical trajectory']);
  add('coherence',['coherence spans the system','когерентность охватывает систему','Kohaerenz umfasst das System'],
      lam/L, lam/L>=1,
      ['a single wavefunction for the whole object','persistent currents','flux quantisation']);
  add('landau',['the Landau spacing beats the temperature','ландауовская щель больше температуры','der Landau-Abstand schlaegt die Temperatur'],
      qrLandau(B,m,T), qrLandau(B,m,T)>=1,
      ['the quantum Hall effect','Shubnikov-de Haas oscillations','Landau levels']);
  add('relativistic',['the Compton wavelength reaches the orbit','комптоновская длина достигает орбиты','die Compton-Wellenlaenge erreicht die Bahn'],
      qrCompton(m)/L, qrCompton(m)/L>=1,
      ['Dirac rather than Schroedinger','pair creation','spin-orbit coupling','the Lamb shift']);
  add('tunnelling',['the barrier is thin enough to pass through','барьер достаточно тонок','die Barriere ist duenn genug'],
      qrTransmission(m,i.barrier_height*QR_E,0,i.barrier_width),
      qrTransmission(m,i.barrier_height*QR_E,0,i.barrier_width)>=1e-6,
      ['tunnelling','alpha decay','the scanning tunnelling microscope','Josephson junctions']);
  return out;
}

